import{_ as i,o as t,c as a,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-11-25 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-11-25 :: Ceph Orchestration Meeting","date":"2019-11-25T00:00:00.000Z","updated":"2019-11-28T00:00:00.000Z","tags":["Ceph Orchestration","Distributed Storage","Kubernetes","Rook","SSH Orchestrator"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-25_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-11-25_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-11-25_-_-_Ceph_Orchestration_Meeting.md"};function o(n,l,s,h,u,p){return t(),a("div",null,[...l[0]||(l[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><ul><li>会议日期：2019年11月25日</li><li>会议时间：具体时间未提及</li></ul><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Sebastian Han</li><li>Juan Miguel</li><li>Travis</li><li>Sage</li><li>Jeff</li><li>其他未提及姓名的参与者</li></ul><h4 id="会议议题" tabindex="-1">会议议题 <a class="header-anchor" href="#会议议题" aria-label="Permalink to &quot;会议议题&quot;">​</a></h4><ol><li><p><strong>KubeCon 回顾</strong></p><ul><li>由于KubeCon活动，部分成员缺席。</li><li>Juan Miguel因家事返回故乡。</li></ul></li><li><p><strong>SSH Orchestrator 更新</strong></p><ul><li>上周在SSH Orchestrator方面进行了大量工作，包括bug修复、权限问题处理和安装模式改进。</li><li>讨论了将Python客户端库添加到Rook，并在Rook Orchestrator中使用。</li></ul></li><li><p><strong>感恩节假期安排</strong></p><ul><li>本周美国感恩节假期，许多成员将休假。</li></ul></li><li><p><strong>SSH Orchestrator 功能扩展</strong></p><ul><li>讨论了增加主机标签功能，类似于Rook的节点标签。</li><li>探讨了使SSH Orchestrator更加声明性。</li><li>讨论了增加调度算法，以随机或基于服务数量的方式分配服务。</li></ul></li><li><p><strong>并行处理和升级问题</strong></p><ul><li>讨论了增加并行处理能力，以提高效率。</li><li>讨论了升级流程，包括检查和实际升级步骤，以及与Rook升级管理的结合。</li></ul></li><li><p><strong>其他议题</strong></p><ul><li>讨论了 blinking lights 功能的实现。</li><li>讨论了Rook版本环境变量的使用和移除。</li><li>讨论了容器镜像版本检查的优化。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ol><li><p><strong>SSH Orchestrator 功能扩展</strong></p><ul><li>增加主机标签功能。</li><li>探索使SSH Orchestrator更加声明性。</li><li>增加简单的调度算法。</li></ul></li><li><p><strong>并行处理和升级问题</strong></p><ul><li>增加并行处理能力。</li><li>优化升级流程，与Rook升级管理结合。</li></ul></li><li><p><strong>其他决定</strong></p><ul><li>移除Rook版本环境变量。</li><li>优化容器镜像版本检查。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><p><strong>SSH Orchestrator 功能扩展</strong></p><ul><li>实现主机标签功能。</li><li>探索声明性配置。</li><li>实现简单的调度算法。</li></ul></li><li><p><strong>并行处理和升级问题</strong></p><ul><li>增加并行处理能力。</li><li>优化升级流程，与Rook升级管理结合。</li></ul></li><li><p><strong>其他行动</strong></p><ul><li>移除Rook版本环境变量。</li><li>优化容器镜像版本检查。</li></ul></li></ol><h4 id="下次会议安排" tabindex="-1">下次会议安排 <a class="header-anchor" href="#下次会议安排" aria-label="Permalink to &quot;下次会议安排&quot;">​</a></h4><ul><li>下次会议定于12月4日，将讨论升级相关事宜。</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>会议中提到的具体技术细节和代码变更需要进一步的技术文档和代码审查。</li></ul><p>以上是本次会议的纪要，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p>',16)])])}const _=i(r,[["render",o]]);export{d as __pageData,_ as default};
